using Microsoft.AspNetCore.Identity;

var builder = WebApplication.CreateBuilder(args);
builder.Services.Configure<IdentityOptions>(o =>
{
    o.Password.RequiredLength = 12; // strong rules at sign-up...
});
var app = builder.Build();

app.MapPost("/login", async (LoginForm form, SignInManager<AppUser> signIn) =>
{
    // ...but unlimited attempts, and failures never lock the account
    var result = await signIn.PasswordSignInAsync(
        form.Email, form.Password, isPersistent: false, lockoutOnFailure: false);
    return result.Succeeded ? Results.Ok() : Results.Unauthorized();
});
app.Run();

using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Identity;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddRateLimiter(o =>
{
    o.RejectionStatusCode = StatusCodes.Status429TooManyRequests;
    o.AddPolicy("login", http => RateLimitPartition.GetSlidingWindowLimiter(
        http.Connection.RemoteIpAddress?.ToString() ?? "unknown",
        _ => new SlidingWindowRateLimiterOptions
        {
            PermitLimit = 10, SegmentsPerWindow = 6,
            Window = TimeSpan.FromMinutes(1),
        }));
});
var app = builder.Build();
app.UseRateLimiter();
app.MapPost("/login", async (LoginForm form, SignInManager<AppUser> signIn) =>
{
    var result = await signIn.PasswordSignInAsync(
        form.Email, form.Password, isPersistent: false, lockoutOnFailure: true);
    return result.Succeeded ? Results.Ok()
        : result.RequiresTwoFactor ? Results.Accepted()
        : Results.Unauthorized(); // same answer for wrong, unknown and locked
}).RequireRateLimiting("login");
app.Run();
